<?php require "../config/auth.php";require "../config/database.php";if(isset($_GET["status"],$_GET["id"])){$pdo->prepare("UPDATE pendaftaran SET status=? WHERE id=?")->execute([$_GET["status"],(int)$_GET["id"]]);header("Location: pendaftaran.php");exit;}$rows=$pdo->query("SELECT * FROM pendaftaran ORDER BY id DESC")->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pendaftaran | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between"><h2>Pendaftaran Anggota</h2><a href="index.php">Dashboard</a></div><div class="table-responsive mt-4"><table class="table table-striped"><thead><tr><th>Nama</th><th>NIM</th><th>Semester</th><th>Divisi</th><th>Alasan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r["nama"])?></td><td><?=e($r["nim"])?></td><td><?=e($r["semester"])?></td><td><?=e($r["divisi"])?></td><td><?=e($r["alasan"])?></td><td><span class="badge bg-secondary"><?=e($r["status"])?></span></td><td><?php foreach(["Diproses","Diterima","Ditolak"] as $s):?><a class="btn btn-sm btn-outline-primary mb-1" href="?id=<?=$r["id"]?>&status=<?=$s?>"><?=$s?></a><?php endforeach;?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>